        ramp.color_at_phase(4, 20, 45_000, ShellPhase::Failed)
    );
    assert_ne!(
        ramp.color_at_phase(10, 20, 22_500, ShellPhase::Working),
        ramp.color_at_phase(10, 20, 22_500, ShellPhase::Verifying)
    );
}

