    message_idx: usize,
    block_idx: usize,
    summary: String,
    content_len: usize,
    blocks_len: usize,
    image_count: usize,
}

impl PlannedPrune {
    /// Byte reduction this replacement realizes, matching the pruner's
    /// accounting exactly.
    fn bytes_reclaimed(&self) -> usize {
        self.content_len
            .saturating_sub(self.summary.len())
            .saturating_add(self.blocks_len)
    }

