95	/// - `extensions` — user-configured extra read-only roots and writable
96	///   device nodes (#5410); skipped when they do not exist on the host
97	///
98	/// # Returns
99	///
100	/// A `Vec<String>` representing the full bwrap invocation.
101	#[cfg(target_os = "linux")]
102	pub fn build_bwrap_command(
103	    cwd: &std::path::Path,
104	    program: &str,
105	    args: &[String],
106	    writable_roots: &[WritableRoot],
107	    network_access: bool,
108	    extensions: &crate::sandbox::BwrapMountExtensions,
109	) -> Vec<String> {
110	    let (writable_mounts, read_only_mounts) = safe_mounts(writable_roots);
111	    let (extra_read_only, device_mounts) = extensions.resolve();
112	    let mut cmd: Vec<String> =
113	        Vec::with_capacity(10 + args.len() + 3 * (writable_mounts.len() + read_only_mounts.len()));
114	
115	    cmd.push(BWRAP_PATH.to_string());
116	
117	    // Isolate every supported namespace by default. `--share-net` selectively
118	    // retains only the network namespace when the resolved policy allows it.
119	    cmd.push("--unshare-all".to_string());
120	    if network_access {
121	        cmd.push("--share-net".to_string());
122	    }
123	
124	    // Read-only bind-mount the entire root filesystem.
125	    cmd.push("--ro-bind".to_string());
126	    cmd.push("/".to_string());
127	    cmd.push("/".to_string());
128	
129	    // Standard container essentials (#5410): a private `/dev` (so device
130	    // nodes exist fresh and writable — `>/dev/null` under the read-only
131	    // root bind is EROFS without this), `/proc`, and a writable isolated
132	    // `/tmp` for toolchain scratch space.
133	    cmd.push("--dev".to_string());
134	    cmd.push("/dev".to_string());
135	    cmd.push("--proc".to_string());
136	    cmd.push("/proc".to_string());
137	    cmd.push("--tmpfs".to_string());
138	    cmd.push("/tmp".to_string());
139	
140	    // User-configured writable device nodes (#5410), e.g. a host `/dev/null`
141	    // when the caller needs the host's, not the fresh private one.
142	    for device in device_mounts {
143	        let device = device.to_string_lossy().into_owned();
144	        cmd.push("--dev-bind".to_string());
145	        cmd.push(device.clone());
146	        cmd.push(device);
147	    }
148	
149	    for root in writable_mounts {
150	        let root = root.to_string_lossy().into_owned();
151	        cmd.push("--bind".to_string());
152	        cmd.push(root.clone());
153	        cmd.push(root);
154	    }
155	
156	    // Re-apply protected descendants after all writable parents so a broad
157	    // writable root cannot make .codewhale/.deepseek exceptions writable.
158	    for root in read_only_mounts {
159	        let root = root.to_string_lossy().into_owned();
160	        cmd.push("--ro-bind".to_string());
161	        cmd.push(root.clone());
162	        cmd.push(root);
163	    }
164	
165	    // User-configured extra read-only roots (#5410) apply last so they can
166	    // narrow (re-mount read-only over) any earlier writable bind if the
167	    // user explicitly lists a path the policy made writable.
168	    for root in extra_read_only {
169	        let root = root.to_string_lossy().into_owned();
170	        cmd.push("--ro-bind".to_string());
171	        cmd.push(root.clone());
172	        cmd.push(root);
173	    }
174	
175	    // Change to the working directory inside the container.
176	    let cwd_str = cwd.to_string_lossy().to_string();
177	    cmd.push("--chdir".to_string());
178	    cmd.push(cwd_str);
179	
180	    // Separator between bwrap args and the command to run.
181	    cmd.push("--".to_string());
182	
183	    // The actual program and its arguments.
184	    cmd.push(program.to_string());
185	    cmd.extend(args.iter().cloned());
186	
187	    cmd
188	}
