import subprocess, re
def patch_round():
    out = subprocess.run(['cargo','test','-p','codewhale-tui','--no-run'],capture_output=True,text=True).stderr
    sites = re.findall(r'missing field `usage_ceiling`[^\n]*\n\s*--> (crates/\S+?\.rs):(\d+)', out)
    if not sites: return 0
    byfile = {}
    for f, ln in sites: byfile.setdefault(f, []).append(int(ln))
    for f, lns in byfile.items():
        lines = open(f).read().splitlines(keepends=True)
        # For each literal start line, find its closing '}' at same brace depth and insert before it
        for start in sorted(lns, reverse=True):
            i = start - 1
            depth = 0
            for j in range(i, len(lines)):
                depth += lines[j].count('{') - lines[j].count('}')
                if j > i and depth == 0:
                    indent = lines[j][:len(lines[j]) - len(lines[j].lstrip())] + '    '
                    lines.insert(j, indent + 'usage_ceiling: None,\n')
                    break
        open(f,'w').write(''.join(lines))
    return len(sites)
total = 0
for _ in range(4):
    n = patch_round()
    total += n
    if n == 0: break
print('patched', total)
